private long tilings(int w) {
    if (w < 4) return 1;
    return tilings(w - 1) + tilings(w - 4);
}

private int countPrimesTrial(long m) {
    int count = 0;
    for (long v = 2; v <= m; v++) {
        boolean prime = true;
        for (long d = 2; d * d <= v; d++) {
            if (v % d == 0) { prime = false; break; }
        }
        if (prime) count++;
    }
    return count;
}

