public int redJohn(int n) {
    int[] f = new int[Math.max(n + 1, 4)];
    f[0] = f[1] = f[2] = f[3] = 1;
    for (int i = 4; i <= n; i++) {
        f[i] = f[i - 1] + f[i - 4];
    }
    int m = f[n];
    if (m < 2) return 0;
    boolean[] composite = new boolean[m + 1];
    int count = 0;
    for (int p = 2; p <= m; p++) {
        if (!composite[p]) {
            count++;
            for (long mult = (long) p * p; mult <= m; mult += p) {
                composite[(int) mult] = true;
            }
        }
    }
    return count;
}

