public int redJohn(int n) {
    if (n < 4) return countPrimes(1);
    int a = 1, b = 1, c = 1, d = 1; // f[0..3]
    for (int i = 4; i <= n; i++) {
        int next = d + a;
        a = b; b = c; c = d; d = next;
    }
    return countPrimes(d);
}

private int countPrimes(int m) {
    if (m < 2) return 0;
    boolean[] composite = new boolean[m + 1];
    int count = 0;
    for (int p = 2; p <= m; p++) {
        if (!composite[p]) {
            count++;
            for (long mult = (long) p * p; mult <= m; mult += p) {
                composite[(int) mult] = true;
            }
        }
    }
    return count;
}

