def red_john(self, n: int) -> int:
    def count_primes(m: int) -> int:
        if m < 2:
            return 0
        is_prime = [True] * (m + 1)
        is_prime[0] = is_prime[1] = False
        p = 2
        while p * p <= m:
            if is_prime[p]:
                for mult in range(p * p, m + 1, p):
                    is_prime[mult] = False
            p += 1
        return sum(is_prime)

    if n < 4:
        return count_primes(1)
    a = b = c = d = 1  # f[0..3]
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, d + a
    return count_primes(d)
